--- server
import { t } from 'kay'
import { checkMessage } from '../contact'
import ContactForm from '../components/contact-form.kay'

const fields = t.Object({
  name: t.String({ maxLength: 200 }),
  email: t.String({ maxLength: 320 }),
  message: t.String({ maxLength: 5000 }),
})

export const send = action(fields, (input, ctx) => {
  const errors = checkMessage(input)

  if (Object.keys(errors).length > 0)
    return ctx.fail(422, { errors })

  return { name: input.name.trim() }
})
---
head
  title Contact
h1 Contact
ContactForm
EOF
cat > src/components/contact-form.kay <<'EOF'
---
import { ActionError } from 'kay'
import { send } from '../routes/contact.kay'
import { checkMessage } from '../contact'
import type { MessageErrors } from '../contact'

const errors = signal<MessageErrors>(send.failed()?.data?.errors ?? {})
const thanked = signal(send.succeeded()?.data.name ?? '')

async function submit(event: SubmitEvent) {
  event.preventDefault()
  const form = event.currentTarget as HTMLFormElement
  const fields = new FormData(form)
  const found = checkMessage({
    name: String(fields.get('name') ?? ''),
    email: String(fields.get('email') ?? ''),
    message: String(fields.get('message') ?? ''),
  })

  errors.set(found)
  thanked.set('')

  if (Object.keys(found).length > 0)
    return

  try {
    thanked.set((await send(fields, { refresh: false })).name)
    form.reset()
  }
  catch (error) {
    if (error instanceof ActionError && error.data !== undefined)
      errors.set((error.data as { errors?: MessageErrors }).errors ?? {})
    else
      throw error
  }
}
---
if thanked
  p(role="status") Thanks, {thanked}! Your message has been sent.
form(action={send} novalidate onSubmit={submit})
  div
    label(for="contact-name") Name
    input#contact-name(type="text" name="name")
    if errors.name
      p.error(id="contact-name-error") {errors.name}
  div
    label(for="contact-email") Email
    input#contact-email(type="email" name="email")
    if errors.email
      p.error(id="contact-email-error") {errors.email}
  div
    label(for="contact-message") Message
    textarea#contact-message(name="message")
    if errors.message
      p.error(id="contact-message-error") {errors.message}
  button(type="submit") Send
EOF
