import { expect, it } from 'bun:test'
import { testSite } from 'kay/test'
import { send } from '../src/routes/contact.kay'

const site = await testSite()

it('refuses an invalid message with every error and the values sent', async () => {
  const page = await site.submit(send, { name: ' ', email: '', message: 'too short' }, { from: '/contact' })

  expect(page.status).toBe(422)
  expect(page.html).toContain('Name is required.')
  expect(page.html).toContain('Email is required.')
  expect(page.html).toContain('Message must be at least 20 characters.')
  expect(page.html).toContain('>too short</textarea>')
})

it('thanks the sender', async () => {
  const page = await site.submit(send, { name: '  Ann  ', email: 'ann@example.com', message: 'A message long enough to pass.' }, { from: '/contact' })

  expect(page.html).toContain('Thanks, <!--[-->Ann<!--]-->! Your message has been sent.')
})

it('answers an island call', async () => {
  const fields = new FormData()
  fields.set('name', ' Bo ')
  fields.set('email', 'bo@example.com')
  fields.set('message', 'Another message long enough.')

  expect(await site.call(send, fields)).toEqual({ name: 'Bo' })
})

it('marks the current section', async () => {
  const book = await site.visit('/books/dracula')
  expect(book.html).toContain('<a href="/books" aria-current="page">Books</a>')

  const missing = await site.visit('/books/missing')
  expect(missing.status).toBe(404)
  expect(missing.html).not.toContain('aria-current')

  const home = await site.visit('/')
  expect(home.html).not.toContain('aria-current')
})
EOF
